discrete RfFrontendSubsystem
port:
    event input real ActivateCommand;
    event input real DataToTransmit;
    event input real IncomingSignal;
    event output real TransmissionComplete;
    event output real ReceptionComplete;
state:
    initial state StandbyState
        when entry() then
            statehold(5);
        end;
        when receive(ActivateCommand) then
            transition(ActiveState);
        end;
    end;

    state ActiveState
        when receive(DataToTransmit) then
            transition(TransmitState);
        end;
        when receive(IncomingSignal) then
            transition(ReceiveState);
        end;
    end;

    state TransmitState
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(ActiveState);
            out
                send(TransmissionComplete, 1);
        end;
    end;

    state ReceiveState
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(ActiveState);
            out
                send(ReceptionComplete, 1);
        end;
    end;
end;
end;

discrete BasebandProcessingSubsystem
port:
    event input real DataSendRequest;
    event input real DataReadyFromRf;
    event output real DataProcessed;
state:
    initial state IdleState
        when entry() then
            statehold(5);
        end;
        when receive(DataSendRequest) then
            transition(DataPreparationState);
        end;
    end;

    state DataPreparationState
        when entry() then
            statehold(10);
        end;
        when receive(DataReadyFromRf) then
            transition(ProcessingState);
        end;
    end;

    state ProcessingState
        when entry() then
            statehold(20);
        end;
        when timeover() then
            transition(IdleState);
            out
                send(DataProcessed, 1);
        end;
    end;
end;
end;

discrete MacSubsystem
port:
    event input real ChannelFree;
    event input real DataToSend;
    event output real SendComplete;
    event output real ReceiveComplete;
state:
    initial state ListeningState
        when entry() then
            statehold(5);
        end;
        when receive(ChannelFree) then
            transition(ContendingState);
        end;
        when receive(DataToSend) then
            transition(SendReceiveState);
        end;
    end;

    state ContendingState
        when entry() then
            statehold(10);
        end;
        when receive(ChannelFree) then
            transition(SendReceiveState);
        end;
    end;

    state SendReceiveState
        when entry() then
            statehold(20);
        end;
        when timeover() then
            transition(ListeningState);
            out
                send(SendComplete, 1);
        end;
        when receive(ChannelFree) then
            transition(ReceiveState);
        end;
    end;

    state ReceiveState
        when entry() then
            statehold(10);
        end;
        when timeover() then
            transition(ListeningState);
            out
                send(ReceiveComplete, 1);
        end;
    end;
end;
end;

couple WifiModuleSystem
import architectureModels.RfFrontendSubsystem as Rf;
import architectureModels.BasebandProcessingSubsystem as Bb;
import architectureModels.MacSubsystem as Mac;
part:
    Rf rfInstance;
    Bb bbInstance;
    Mac macInstance;
connection:
    connect(rfInstance.TransmissionComplete, bbInstance.DataSendRequest);
    connect(rfInstance.ReceptionComplete, bbInstance.DataReadyFromRf);
    connect(bbInstance.DataProcessed, macInstance.DataReceiveRequest);
    connect(macInstance.ChannelStatus, rfInstance.ActivateCommand);
    connect(macInstance.DataTransmitRequest, rfInstance.DataToTransmit);
    connect(macInstance.SignalReceiveStatus, rfInstance.IncomingSignal);
end;
